/// The reserved strip: fits the pill at the app's 1.3x text-scale cap.
///
/// Known gap (run manager, 2026-10-05): the pill's tap target is this
/// 30 px strip, under [VistaSize.tapTarget]. A pad above the strip would
/// sit on footers that end flush on it (make-market footer, ChartSheet
/// Long/Short, your-market 'Make a call'), which spec 03 forbids, and
/// raising the slot costs every screen 14 px. Closing it is the manager's
/// call: raise the slot, or give those footers a 14 px gap first.
static const double slot = 30;

static const Color surfaceRaised = Color(0xFF333333);

/// Modal scrim behind bottom sheets (Figma: black at 45%).
static const Color scrim = Color(0x73000000);

static const double card = 20;

/// Top corners of a bottom sheet.
static const double sheet = 24;

/// The breakout label is the last event the trace reaches.
Finder get breakoutLabel => find.text(r'Broke $2,950');

/// The simulated pill's label.
const pill = 'Simulated · fixture-v1';

/// The pill is on screen, on top, and covers none of [targets].
void expectPillClear(WidgetTester tester, Finder targets) {
  final badge = find.bySemanticsLabel(pill);
  expect(badge.hitTestable(), findsOneWidget);
  expect(targets, findsWidgets);
  final rect = tester.getRect(badge);
  for (var i = 0; i < targets.evaluate().length; i++) {
    final target = tester.getRect(targets.at(i));
    expect(rect.overlaps(target), isFalse, reason: '$rect covers $target');
  }
}

